SELECT 
FROM sys_import_export_template template
INNER JOIN sys_file file ON file.id = template.file_id
WHERE template.module_code = #{moduleCode}
  AND template.template_type = #{templateType}
  AND template.version = #{version}

SELECT 
FROM sys_import_export_template template
INNER JOIN sys_file file ON file.id = template.file_id


        AND LOWER(template.template_name) LIKE CONCAT('%', LOWER(#{templateName}), '%')


        AND template.template_type = #{templateType}


        AND template.module_code = #{moduleCode}


        AND template.status = #{status}


ORDER BY template.updated_at DESC, template.id DESC
LIMIT 200

mapper.update:
UPDATE sys_import_export_template
SET version_no = version_no + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND version_no = #{expectedVersion}
  AND status = 'DISABLED'
